from pathlib import Path

ROOT=Path(__file__).resolve().parent
FILES={
    'backend/player_intelligence_v85.py': 'from __future__ import annotations\n\nimport json\nimport math\nimport re\nimport sqlite3\nimport unicodedata\nfrom collections import defaultdict\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\nfrom statistics import pstdev\nfrom typing import Any\n\nimport pandas as pd\n\nROOT = Path(__file__).resolve().parents[1]\nOUT = ROOT / "frontend" / "data"\nCACHE = ROOT / "data" / "cache" / "player_intelligence_v85"\nDB_PATH = ROOT / "data" / "tennis.db"\nRESULTS_PATH = OUT / "results.json"\nHISTORY_PATH = OUT / "history.json"\nMETA_PATH = OUT / "meta.json"\nTELEMETRY_PATH = OUT / "model_telemetry_v84c.json"\nPROFILE_CACHE_PATH = CACHE / "profiles.json"\nSTATE_PATH = CACHE / "state.json"\nVERSION = "v8.5"\nPRIMARY_DAYS = 365\nFALLBACK_DAYS = 730\nWINDOWS = (5, 10, 20)\nMIN_PROFILE_N = 3\nCAPTURE_CUTOFF_MINUTES = 5\nSELECT_THRESHOLD = 0.65\nMAX_FROZEN = 12\nGENERATOR_TOP = 2\n\n\ndef _read(path: Path, fallback):\n    try:\n        x = json.loads(path.read_text(encoding="utf-8"))\n        return x\n    except (FileNotFoundError, OSError, json.JSONDecodeError):\n        return fallback\n\n\ndef _write(path: Path, value) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    tmp = path.with_suffix(path.suffix + ".tmp")\n    tmp.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")\n    tmp.replace(path)\n\n\ndef _num(value, default=None):\n    try:\n        x = float(value)\n        return x if math.isfinite(x) else default\n    except (TypeError, ValueError):\n        return default\n\n\ndef _clamp(value, lo=0.0, hi=1.0):\n    return max(lo, min(hi, float(value)))\n\n\ndef _dt(value):\n    try:\n        d = datetime.fromisoformat(str(value or "").replace("Z", "+00:00"))\n        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)\n    except Exception:\n        return None\n\n\ndef _key(value: Any) -> str:\n    s = unicodedata.normalize("NFKD", str(value or "")).encode("ascii", "ignore").decode().casefold()\n    return " ".join(re.sub(r"[^a-z0-9]+", " ", s).split())\n\n\ndef _match_key(entry: dict) -> str:\n    mid = entry.get("match_id") if entry.get("match_id") is not None else entry.get("id")\n    if mid is not None and str(mid) != "":\n        return f"id:{mid}"\n    return "|".join([\n        _key(entry.get("p1")), _key(entry.get("p2")),\n        str(entry.get("scheduled_time") or "")[:10], _key(entry.get("tournament")),\n    ])\n\n\ndef _surface(value: Any) -> str:\n    x = str(value or "").strip().lower()\n    if "indoor" in x and "hard" in x:\n        return "indoor"\n    if x in ("hard", "clay", "grass", "carpet", "indoor"):\n        return x\n    if "grass" in x:\n        return "grass"\n    if "clay" in x:\n        return "clay"\n    if "hard" in x:\n        return "hard"\n    return x or "unknown"\n\n\ndef _prob(v):\n    x = _num(v)\n    if x is None:\n        return None\n    if x > 1.0:\n        x /= 100.0\n    return _clamp(x, .01, .99)\n\n\ndef _pct(v):\n    x = _num(v)\n    if x is None:\n        return None\n    return x * 100.0 if 0 <= x <= 1 else x\n\n\ndef _range_score(v, lo, hi):\n    x = _num(v)\n    if x is None or hi <= lo:\n        return None\n    if 0 <= x <= 1 and hi > 1:\n        x *= 100\n    return _clamp((x - lo) / (hi - lo), 0, 1) * 100\n\n\ndef _weighted(values):\n    rows = [(float(v), float(w)) for v, w in values if v is not None and w > 0]\n    if not rows:\n        return None\n    z = sum(w for _, w in rows)\n    return sum(v * w for v, w in rows) / z if z else None\n\n\ndef _opp_strength(rank) -> float:\n    """0..1 rank-based difficulty proxy. Not ELO; deliberately bounded."""\n    r = _num(rank)\n    if r is None or r <= 0:\n        return .50\n    r = min(2000.0, max(1.0, r))\n    return _clamp(1.0 - math.log(r) / math.log(2000.0), 0.0, 1.0)\n\n\ndef _quality(n: int, coverage: float, fallback_used: bool) -> str:\n    if n >= 10 and coverage >= .78 and not fallback_used:\n        return "HIGH"\n    if n >= 5 and coverage >= .58:\n        return "MEDIUM"\n    if n >= MIN_PROFILE_N:\n        return "LOW"\n    return "N/D"\n\n\ndef _quality_rank(q: str) -> int:\n    return {"N/D": 0, "LOW": 1, "MEDIUM": 2, "HIGH": 3}.get(str(q or "N/D").upper(), 0)\n\n\ndef _quality_min(a: str, b: str) -> str:\n    return min((a, b), key=_quality_rank)\n\n\ndef _source_fingerprint(df: pd.DataFrame) -> str:\n    if df is None or df.empty:\n        return "0:none"\n    d = pd.to_datetime(df.get("date"), errors="coerce") if "date" in df.columns else pd.Series(dtype="datetime64[ns]")\n    mx = "none" if d.empty or d.dropna().empty else str(d.max().date())\n    return f"{len(df)}:{mx}"\n\n\n\ndef _parse_tourney_date(value):\n    try:\n        s = str(value or "").strip()\n        if re.fullmatch(r"\\d+(\\.0+)?", s):\n            s = str(int(float(s)))\n        d = pd.to_datetime(s, format="%Y%m%d", errors="coerce")\n        return d\n    except Exception:\n        return pd.NaT\n\n\ndef _set_pairs(score) -> list[tuple[int, int]]:\n    if not isinstance(score, str):\n        return []\n    return [(int(a), int(b)) for a, b in re.findall(r"(\\d+)\\s*[-:]\\s*(\\d+)", score)][:5]\n\n\ndef _raw_enrichment() -> pd.DataFrame:\n    """Read already-cached TennisMyLife CSVs. No network and no new API calls."""\n    rows = []\n    for path in sorted((ROOT / "data" / "cache").glob("*.csv.gz")):\n        try:\n            df = pd.read_csv(path, compression="gzip", low_memory=False)\n        except Exception:\n            continue\n        if df.empty or "winner_name" not in df.columns or "loser_name" not in df.columns:\n            continue\n        for _, r in df.iterrows():\n            wn, ln = r.get("winner_name"), r.get("loser_name")\n            if not isinstance(wn, str) or not isinstance(ln, str):\n                continue\n            pairs = _set_pairs(str(r.get("score") or ""))\n            date = _parse_tourney_date(r.get("tourney_date"))\n            surf = _surface(r.get("surface"))\n            for side, name, opp in (("w", wn, ln), ("l", ln, wn)):\n                out = {\n                    "date": date,\n                    "surface": surf,\n                    "player_key": _key(name),\n                    "opponent_key": _key(opp),\n                    "aces": _num(r.get(f"{side}_ace"), _num(r.get(f"{side}_aces"))),\n                    "double_faults": _num(r.get(f"{side}_df"), _num(r.get(f"{side}_double_faults"))),\n                    "score_text": str(r.get("score") or ""),\n                }\n                for i in range(5):\n                    if i < len(pairs):\n                        a, b = pairs[i]\n                        won = (a > b) if side == "w" else (b > a)\n                        out[f"set{i+1}_won"] = 1.0 if won else 0.0\n                    else:\n                        out[f"set{i+1}_won"] = None\n                out["sets_played_rich"] = float(len(pairs)) if pairs else None\n                rows.append(out)\n    if not rows:\n        return pd.DataFrame()\n    x = pd.DataFrame(rows)\n    x = x.drop_duplicates(subset=["date", "surface", "player_key", "opponent_key", "score_text"], keep="last")\n    return x\n\n\ndef _merge_raw_enrichment(df: pd.DataFrame) -> pd.DataFrame:\n    rich = _raw_enrichment()\n    if df is None or df.empty or rich.empty:\n        return df\n    x = df.copy()\n    if "date" in x.columns:\n        x["date"] = pd.to_datetime(x["date"], errors="coerce").dt.normalize()\n    rich["date"] = pd.to_datetime(rich["date"], errors="coerce").dt.normalize()\n    if "surface" in x.columns:\n        x["surface"] = x["surface"].astype(str).map(_surface)\n    cols = ["date", "surface", "player_key", "opponent_key"]\n    use = rich.drop_duplicates(subset=cols, keep="last")\n    x = x.merge(use, on=cols, how="left", suffixes=("", "_rich"))\n    if "sets_played_rich" in x.columns:\n        base = pd.to_numeric(x.get("sets_played"), errors="coerce")\n        rr = pd.to_numeric(x.get("sets_played_rich"), errors="coerce")\n        x["sets_played"] = base.where(base.notna(), rr)\n    return x\n\n\ndef _load_long_df() -> pd.DataFrame:\n    if not DB_PATH.exists():\n        return pd.DataFrame()\n    try:\n        with sqlite3.connect(DB_PATH) as con:\n            df = pd.read_sql_query("select * from player_matches", con)\n    except Exception:\n        return pd.DataFrame()\n    if "date" in df.columns:\n        df["date"] = pd.to_datetime(df["date"], errors="coerce")\n    return _merge_raw_enrichment(df)\n\n\ndef _metric_pack(x: pd.DataFrame, col: str, prior: float | None = None) -> dict:\n    if x is None or x.empty or col not in x.columns:\n        return {"raw": None, "adjusted": None, "n": 0, "volatility": None}\n    vals = pd.to_numeric(x[col], errors="coerce")\n    good = vals.notna()\n    if not good.any():\n        return {"raw": None, "adjusted": None, "n": 0, "volatility": None}\n    raw_vals = vals[good].astype(float).tolist()\n    raw = float(sum(raw_vals) / len(raw_vals))\n    weighted_rows = []\n    for pos, (idx, row) in enumerate(x[good].iterrows()):\n        v = _num(row.get(col))\n        if v is None:\n            continue\n        recency = .91 ** pos\n        difficulty = .72 + .56 * _opp_strength(row.get("opponent_rank"))\n        weighted_rows.append((v, recency * difficulty))\n    adjusted = _weighted(weighted_rows)\n    n = len(raw_vals)\n    if adjusted is not None and prior is not None:\n        adjusted = (adjusted * n + float(prior) * 3.0) / (n + 3.0)\n    vol = pstdev(raw_vals) if len(raw_vals) >= 2 else 0.0\n    return {\n        "raw": round(raw, 5),\n        "adjusted": round(adjusted, 5) if adjusted is not None else None,\n        "n": n,\n        "volatility": round(vol, 5),\n    }\n\n\ndef _surface_priors(df: pd.DataFrame, surface: str, as_of: pd.Timestamp) -> dict:\n    if df is None or df.empty:\n        return {}\n    x = df.copy()\n    if "date" in x.columns:\n        x = x[x["date"].isna() | (x["date"] < as_of)]\n    if "surface" in x.columns:\n        sx = x[x["surface"].astype(str).map(_surface) == surface]\n        if len(sx) >= 100:\n            x = sx\n    cols = [\n        "won", "hold_rate", "break_rate", "serve_points_won", "return_points_won",\n        "first_serve_won", "second_serve_won", "first_set_won", "second_set_won",\n        "second_after_first_win", "second_after_first_loss", "third_set_won",\n        "set4_won", "set5_won", "aces", "double_faults",\n        "first_set_over85", "first_set_over95", "first_set_over105",\n    ]\n    out = {}\n    for c in cols:\n        if c in x.columns:\n            s = pd.to_numeric(x[c], errors="coerce").dropna()\n            if not s.empty:\n                out[c] = float(s.mean())\n    return out\n\n\ndef _window_pack(x: pd.DataFrame, n: int, priors: dict) -> dict:\n    y = x.head(n).copy()\n    cols = [\n        "won", "hold_rate", "break_rate", "serve_points_won", "return_points_won",\n        "first_serve_won", "second_serve_won", "first_set_won", "second_set_won",\n        "second_after_first_win", "second_after_first_loss", "third_set_won",\n        "set4_won", "set5_won", "aces", "double_faults",\n        "first_set_over85", "first_set_over95", "first_set_over105",\n    ]\n    metrics = {c: _metric_pack(y, c, priors.get(c)) for c in cols}\n    opp = [_opp_strength(v) for v in y.get("opponent_rank", pd.Series(dtype=float)).tolist()]\n    ranks = pd.to_numeric(y.get("rank", pd.Series(dtype=float)), errors="coerce").dropna()\n    set_counts = pd.to_numeric(y.get("sets_played", pd.Series(dtype=float)), errors="coerce").dropna()\n    return {\n        "requested": n,\n        "sample_matches": int(len(y)),\n        "metrics": metrics,\n        "avg_opponent_strength": round(sum(opp) / len(opp), 4) if opp else None,\n        "latest_rank": int(round(float(ranks.iloc[0]))) if not ranks.empty and ranks.iloc[0] > 0 else None,\n        "avg_sets_played": round(float(set_counts.mean()), 2) if not set_counts.empty else None,\n        "bo5_observed": int((set_counts >= 4).sum()) if not set_counts.empty else 0,\n        "set4_win": _metric_pack(y, "set4_won", priors.get("set4_won")),\n        "set5_win": _metric_pack(y, "set5_won", priors.get("set5_won")),\n        "aces": _metric_pack(y, "aces", None),\n        "double_faults": _metric_pack(y, "double_faults", None),\n    }\n\n\ndef _trend(x: pd.DataFrame) -> dict:\n    if x is None or len(x) < 6:\n        return {}\n    a, b = x.head(5), x.iloc[5:10]\n    out = {}\n    for c in ("won", "hold_rate", "break_rate", "serve_points_won", "return_points_won", "first_set_won"):\n        if c not in x.columns:\n            continue\n        av = pd.to_numeric(a[c], errors="coerce").dropna()\n        bv = pd.to_numeric(b[c], errors="coerce").dropna()\n        if len(av) >= 2 and len(bv) >= 2:\n            out[c] = round(100 * (float(av.mean()) - float(bv.mean())), 1)\n    return out\n\n\ndef _profile_indexes(profile: dict, early_ehs=None) -> dict:\n    w = profile.get("windows", {}).get("10") or profile.get("windows", {}).get("5") or {}\n    m = w.get("metrics") or {}\n    val = lambda k: (m.get(k) or {}).get("adjusted")\n    serve = _weighted([\n        (_range_score(val("hold_rate"), .60, .90), .38),\n        (_range_score(val("serve_points_won"), .50, .72), .25),\n        (_range_score(val("first_serve_won"), .55, .85), .20),\n        (_range_score(val("second_serve_won"), .35, .65), .17),\n    ])\n    ret = _weighted([\n        (_range_score(val("break_rate"), .10, .45), .46),\n        (_range_score(val("return_points_won"), .28, .52), .54),\n    ])\n    form = _weighted([\n        (_pct(val("won")), .45), (_pct(val("first_set_won")), .32), (_pct(val("second_set_won")), .23)\n    ])\n    mental = _weighted([\n        (_pct(val("second_after_first_win")), .32),\n        (_pct(val("second_after_first_loss")), .32),\n        (_pct(val("third_set_won")), .20),\n        (_pct(val("set5_won")), .12),\n        (_pct(val("second_set_won")), .04),\n    ])\n    early = _pct(early_ehs)\n    rank = w.get("latest_rank")\n    rank_idx = None if rank is None else 100 * _opp_strength(rank)\n    overall = _weighted([(serve, .25), (ret, .22), (form, .20), (mental, .13), (early, .08), (rank_idx, .12)])\n    return {\n        "serve": round(serve, 1) if serve is not None else None,\n        "return": round(ret, 1) if ret is not None else None,\n        "form": round(form, 1) if form is not None else None,\n        "mental": round(mental, 1) if mental is not None else None,\n        "early": round(early, 1) if early is not None else None,\n        "rank_strength": round(rank_idx, 1) if rank_idx is not None else None,\n        "overall": round(overall, 1) if overall is not None else None,\n    }\n\n\ndef build_profile(df: pd.DataFrame, player: str, surface: str, as_of, early_ehs=None) -> dict:\n    if df is None or df.empty:\n        return {"player": player, "surface": surface, "quality": "N/D", "windows": {}, "indexes": {}}\n    k = _key(player)\n    x = df[df["player_key"].astype(str) == k].copy() if "player_key" in df.columns else df[df["player"].map(_key) == k].copy()\n    cut = pd.to_datetime(as_of, utc=True, errors="coerce")\n    if pd.isna(cut):\n        cut = pd.Timestamp(datetime.now(timezone.utc))\n    cut_naive = cut.tz_convert(None) if getattr(cut, "tzinfo", None) else cut\n    if "date" in x.columns:\n        x = x[x["date"].isna() | (x["date"] < cut_naive.normalize())]\n    if "surface" in x.columns:\n        x = x[x["surface"].astype(str).map(_surface) == surface]\n    x = x.sort_values("date", ascending=False, na_position="last") if "date" in x.columns else x\n\n    primary = x\n    if "date" in x.columns:\n        primary = x[x["date"].isna() | (x["date"] >= cut_naive - pd.Timedelta(days=PRIMARY_DAYS))]\n    fallback_used = False\n    usable = primary\n    if len(primary) < 5 and "date" in x.columns:\n        usable = x[x["date"].isna() | (x["date"] >= cut_naive - pd.Timedelta(days=FALLBACK_DAYS))]\n        fallback_used = len(usable) > len(primary)\n    usable = usable.head(20)\n    priors = _surface_priors(df, surface, cut_naive)\n    coverage_cols = [c for c in ("hold_rate", "break_rate", "serve_points_won", "return_points_won", "first_set_won") if c in usable.columns]\n    coverage = 0.0 if not coverage_cols or usable.empty else sum(float(pd.to_numeric(usable[c], errors="coerce").notna().mean()) for c in coverage_cols) / len(coverage_cols)\n    quality = _quality(len(usable), coverage, fallback_used)\n    windows = {str(n): _window_pack(usable, n, priors) for n in WINDOWS}\n    profile = {\n        "version": VERSION,\n        "player": player,\n        "player_key": k,\n        "surface": surface,\n        "as_of": cut.isoformat(),\n        "primary_days": PRIMARY_DAYS,\n        "fallback_days": FALLBACK_DAYS,\n        "fallback_used": fallback_used,\n        "sample_matches": int(len(usable)),\n        "quality": quality,\n        "coverage": round(coverage, 4),\n        "windows": windows,\n        "trend": _trend(usable),\n        "data_policy": "same_surface_only_l5_l10_l20_rank_weighted_shrinkage",\n    }\n    profile["indexes"] = _profile_indexes(profile, early_ehs)\n    return profile\n\n\ndef _metric(profile: dict, key: str, window="10"):\n    p = (((profile or {}).get("windows") or {}).get(str(window)) or {}).get("metrics") or {}\n    return ((p.get(key) or {}).get("adjusted"))\n\n\ndef _idx(profile: dict, key: str):\n    return _num(((profile or {}).get("indexes") or {}).get(key))\n\n\ndef _matchup_summary(p1: dict, p2: dict, best_of=None) -> dict:\n    q = _quality_min(p1.get("quality", "N/D"), p2.get("quality", "N/D"))\n    p1i, p2i = _idx(p1, "overall"), _idx(p2, "overall")\n    serve_edge = None if _idx(p1, "serve") is None or _idx(p2, "return") is None else _idx(p1, "serve") - _idx(p2, "return")\n    return_edge = None if _idx(p1, "return") is None or _idx(p2, "serve") is None else _idx(p1, "return") - _idx(p2, "serve")\n    form_edge = None if _idx(p1, "form") is None or _idx(p2, "form") is None else _idx(p1, "form") - _idx(p2, "form")\n    overall_edge = None if p1i is None or p2i is None else p1i - p2i\n    reasons = []\n    for label, edge in (("serwis vs return", serve_edge), ("return vs serwis", return_edge), ("forma", form_edge), ("profil łączny", overall_edge)):\n        if edge is not None and abs(edge) >= 4:\n            reasons.append({"factor": label, "edge_p1": round(edge, 1)})\n    reasons = sorted(reasons, key=lambda x: -abs(x["edge_p1"]))[:3]\n    return {\n        "quality": q,\n        "best_of": int(best_of) if _num(best_of) in (3, 5) else None,\n        "p1_overall": p1i,\n        "p2_overall": p2i,\n        "edge_p1": round(overall_edge, 1) if overall_edge is not None else None,\n        "serve_edge_p1": round(serve_edge, 1) if serve_edge is not None else None,\n        "return_edge_p1": round(return_edge, 1) if return_edge is not None else None,\n        "form_edge_p1": round(form_edge, 1) if form_edge is not None else None,\n        "reasons": reasons,\n    }\n\n\ndef _sigmoid(x):\n    return 1.0 / (1.0 + math.exp(-max(-8.0, min(8.0, float(x)))))\n\n\ndef _winner_probability(profile: dict, other: dict, set_no=0) -> float | None:\n    if _quality_rank(profile.get("quality")) == 0 or _quality_rank(other.get("quality")) == 0:\n        return None\n    a = _idx(profile, "overall")\n    b = _idx(other, "overall")\n    if a is None or b is None:\n        return None\n    if set_no == 1:\n        av, bv = _metric(profile, "first_set_won"), _metric(other, "first_set_won")\n    elif set_no == 2:\n        av, bv = _metric(profile, "second_set_won"), _metric(other, "second_set_won")\n    elif set_no == 3:\n        av, bv = _metric(profile, "third_set_won"), _metric(other, "third_set_won")\n    else:\n        av, bv = _metric(profile, "won"), _metric(other, "won")\n    hist_edge = 0.0 if av is None or bv is None else (av - bv) * 100\n    edge = .72 * (a - b) + .28 * hist_edge\n    p = _sigmoid(edge / 13.5)\n    return _clamp(p, .30, .70)\n\n\ndef _over_probability(p1: dict, p2: dict, line: float) -> float | None:\n    line = _num(line)\n    if line is None:\n        return None\n    if line <= 8.5:\n        key = "first_set_over85"\n    elif line <= 9.5:\n        key = "first_set_over95"\n    elif line <= 10.5:\n        key = "first_set_over105"\n    else:\n        return None\n    vals = [_metric(p1, key), _metric(p2, key)]\n    vals = [v for v in vals if v is not None]\n    if not vals:\n        return None\n    p = sum(vals) / len(vals)\n    # High holds push a little toward longer sets; bounded to avoid double counting.\n    holds = [v for v in (_metric(p1, "hold_rate"), _metric(p2, "hold_rate")) if v is not None]\n    if holds:\n        p += max(-.05, min(.05, (sum(holds) / len(holds) - .74) * .35))\n    return _clamp(p, .20, .90)\n\n\ndef _balanced_state_probability(p1: dict, p2: dict, checkpoint: int) -> float | None:\n    h1, h2 = _metric(p1, "hold_rate"), _metric(p2, "hold_rate")\n    if h1 is None or h2 is None:\n        return None\n    pair_hold = _clamp(h1 * h2, .10, .98)\n    pairs = max(1, int(checkpoint) // 2)\n    return _clamp(pair_hold ** pairs, .10, .92)\n\n\ndef signal_probability(match: dict, signal: dict) -> tuple[float | None, list[str]]:\n    pi = match.get("player_intelligence_v85") or {}\n    p1 = (pi.get("profiles") or {}).get("p1") or {}\n    p2 = (pi.get("profiles") or {}).get("p2") or {}\n    market = str(signal.get("market") or "").lower()\n    pick = str(signal.get("pick") or "")\n    nk = _key(pick)\n    p1k, p2k = _key(match.get("p1")), _key(match.get("p2"))\n    reasons = []\n\n    if market in ("match_winner", "match_win") or "match_win" in str(signal.get("key") or ""):\n        p = _winner_probability(p1, p2, 0)\n        if p is None:\n            return None, []\n        out = p if nk == p1k else (1 - p if nk == p2k else None)\n    elif market in ("set1_winner", "set1_win"):\n        p = _winner_probability(p1, p2, 1)\n        out = p if nk == p1k else (1 - p if nk == p2k else None)\n    elif market in ("set2_winner", "set2_win"):\n        p = _winner_probability(p1, p2, 2)\n        out = p if nk == p1k else (1 - p if nk == p2k else None)\n    elif market in ("set3_winner", "set3_win"):\n        p = _winner_probability(p1, p2, 3)\n        out = p if nk == p1k else (1 - p if nk == p2k else None)\n    elif market == "set1_total":\n        p = _over_probability(p1, p2, _num(signal.get("line")))\n        if p is None:\n            return None, []\n        out = p if nk == "over" else (1 - p if nk == "under" else None)\n    elif market == "game_state" or market.startswith("state"):\n        cp = signal.get("checkpoint")\n        if cp is None:\n            m = re.search(r"state\\D*([246])", str(signal.get("key") or market))\n            cp = int(m.group(1)) if m else None\n        try:\n            cp = int(cp)\n        except Exception:\n            return None, []\n        expected = {2: "1:1", 4: "2:2", 6: "3:3"}.get(cp)\n        if pick != expected:\n            return None, []\n        out = _balanced_state_probability(p1, p2, cp)\n    else:\n        return None, []\n\n    if out is None:\n        return None, []\n    summary = pi.get("matchup") or {}\n    for r in summary.get("reasons") or []:\n        edge = _num(r.get("edge_p1"))\n        if edge is None:\n            continue\n        direction = "P1" if edge > 0 else "P2"\n        reasons.append(f"{r.get(\'factor\')}: {direction} {abs(edge):.1f}")\n    return _clamp(out, .05, .95), reasons[:3]\n\n\ndef _shadow(base: float, player_p: float, quality: str) -> tuple[float, float]:\n    q = str(quality or "N/D").upper()\n    alpha, cap = {\n        "HIGH": (.25, .04), "MEDIUM": (.15, .02), "LOW": (.08, .01), "N/D": (0.0, 0.0)\n    }.get(q, (0.0, 0.0))\n    raw = base + alpha * (player_p - base)\n    shift = max(-cap, min(cap, raw - base))\n    return _clamp(base + shift, .01, .99), shift\n\n\ndef _support(player_p: float) -> int:\n    return int(round(max(-10, min(10, (player_p - .50) / .03))))\n\n\ndef _cache_key(player: str, surface: str, as_of: str, fingerprint: str) -> str:\n    return f"{_key(player)}|{surface}|{str(as_of)[:10]}|{fingerprint}"\n\n\ndef pre(now=None) -> dict:\n    now = now or datetime.now(timezone.utc)\n    results = _read(RESULTS_PATH, [])\n    meta = _read(META_PATH, {})\n    cache = _read(PROFILE_CACHE_PATH, {"version": VERSION, "profiles": {}})\n    if not isinstance(cache, dict):\n        cache = {"version": VERSION, "profiles": {}}\n    profiles_cache = cache.setdefault("profiles", {})\n    df = _load_long_df()\n    fp = _source_fingerprint(df)\n    built = reused = 0\n\n    out = []\n    for match in results if isinstance(results, list) else []:\n        m = dict(match)\n        surf = _surface(m.get("surface"))\n        sides = {}\n        for side in ("p1", "p2"):\n            name = m.get(side)\n            early = (((m.get("early_hold_v7") or {}).get(side) or {}).get("ehs"))\n            ck = _cache_key(name, surf, m.get("scheduled_time"), fp)\n            p = profiles_cache.get(ck)\n            if isinstance(p, dict) and p.get("version") == VERSION:\n                reused += 1\n            else:\n                p = build_profile(df, str(name or ""), surf, m.get("scheduled_time"), early)\n                profiles_cache[ck] = p\n                built += 1\n            sides[side] = p\n        matchup = _matchup_summary(sides["p1"], sides["p2"], m.get("best_of"))\n        m["player_intelligence_v85"] = {\n            "version": VERSION,\n            "mode": "SHADOW",\n            "surface": surf,\n            "profiles": sides,\n            "matchup": matchup,\n            "api_calls": 0,\n            "cache_policy": "reuse_existing_history_no_new_api",\n            "updated_at": now.isoformat(),\n        }\n        out.append(m)\n\n    cache["version"] = VERSION\n    cache["source_fingerprint"] = fp\n    cache["updated_at"] = now.isoformat()\n    # Avoid unbounded growth from per-day keys; keep newest 6000 cached profiles.\n    if len(profiles_cache) > 6000:\n        keep = list(profiles_cache.items())[-6000:]\n        cache["profiles"] = dict(keep)\n    _write(PROFILE_CACHE_PATH, cache)\n    _write(RESULTS_PATH, out)\n    if not isinstance(meta, dict):\n        meta = {}\n    meta.update({\n        "player_intelligence_v85_version": VERSION,\n        "player_intelligence_v85_mode": "SHADOW",\n        "player_intelligence_v85_profiles_built": built,\n        "player_intelligence_v85_profiles_reused": reused,\n        "player_intelligence_v85_api_calls": 0,\n        "player_intelligence_v85_updated_at": now.isoformat(),\n    })\n    _write(META_PATH, meta)\n    return {"status": "ok", "matches": len(out), "built": built, "reused": reused, "api_calls": 0}\n\n\ndef _decorate_post(results: list[dict]) -> list[dict]:\n    out = []\n    for match in results or []:\n        m = dict(match)\n        pi = m.get("player_intelligence_v85") or {}\n        quality = ((pi.get("matchup") or {}).get("quality")) or "N/D"\n        auto = dict(m.get("autolearn_v84") or {})\n        sigs = []\n        for s0 in auto.get("signals") or []:\n            s = dict(s0)\n            pp, reasons = signal_probability(m, s)\n            base = _prob(s.get("ensemble"))\n            if pp is not None and base is not None:\n                shadow, shift = _shadow(base, pp, quality)\n                s["player_intelligence_v85"] = {\n                    "version": VERSION,\n                    "mode": "SHADOW",\n                    "quality": quality,\n                    "probability": round(pp * 100, 1),\n                    "ensemble_base": round(base * 100, 1),\n                    "shadow_score": round(shadow * 100, 1),\n                    "shadow_shift_pp": round(shift * 100, 1),\n                    "support_score": _support(pp),\n                    "reasons": reasons,\n                }\n            sigs.append(s)\n        auto["signals"] = sigs\n        auto["by_key"] = {str(x.get("key")): x for x in sigs if x.get("key")}\n        m["autolearn_v84"] = auto\n        out.append(m)\n    return out\n\n\ndef _capture_and_settle(history: list[dict], results: list[dict], now: datetime) -> tuple[list[dict], int, int]:\n    current = {_match_key(m): m for m in results or []}\n    captured = settled = 0\n    out = []\n    for entry0 in history or []:\n        e = dict(entry0)\n        auto_frozen = e.get("autolearn_signals_v84") or []\n        existing = e.get("player_intelligence_signals_v85") or []\n        if existing:\n            amap = {str(s.get("key")): s for s in auto_frozen if s.get("key")}\n            rows = []\n            for p0 in existing:\n                p = dict(p0)\n                if p.get("result") not in ("hit", "miss"):\n                    a = amap.get(str(p.get("key"))) or {}\n                    if a.get("result") in ("hit", "miss"):\n                        p["result"] = a.get("result")\n                        p["settled_at"] = now.isoformat()\n                        settled += 1\n                rows.append(p)\n            e["player_intelligence_signals_v85"] = rows\n            out.append(e)\n            continue\n\n        if e.get("status") not in ("pending", "upcoming") or not auto_frozen:\n            out.append(e); continue\n        scheduled = _dt(e.get("scheduled_time"))\n        if scheduled is None or scheduled <= now + timedelta(minutes=CAPTURE_CUTOFF_MINUTES):\n            out.append(e); continue\n        m = current.get(_match_key(e))\n        if not m:\n            out.append(e); continue\n        bykey = ((m.get("autolearn_v84") or {}).get("by_key") or {})\n        rows = []\n        for a in auto_frozen[:MAX_FROZEN]:\n            s = bykey.get(str(a.get("key"))) or {}\n            p = s.get("player_intelligence_v85") or {}\n            if _num(p.get("probability")) is None:\n                continue\n            rows.append({\n                "key": a.get("key"), "label": a.get("label"), "market": a.get("market"),\n                "pick": a.get("pick"), "line": a.get("line"), "checkpoint": a.get("checkpoint"),\n                "player_probability": p.get("probability"),\n                "ensemble_base": p.get("ensemble_base"),\n                "shadow_score": p.get("shadow_score"),\n                "support_score": p.get("support_score"),\n                "quality": p.get("quality"),\n                "reasons": p.get("reasons") or [],\n                "generator_production_selected": bool(a.get("generator_selected")),\n                "generator_shadow_selected": False,\n                "result": "pending",\n                "tracker_version": VERSION,\n            })\n        top = sorted([r for r in rows if _num(r.get("shadow_score"), 0) >= 65], key=lambda r: -_num(r.get("shadow_score"), 0))[:GENERATOR_TOP]\n        top_keys = {str(r.get("key")) for r in top}\n        for r in rows:\n            r["generator_shadow_selected"] = str(r.get("key")) in top_keys\n        if rows:\n            e["player_intelligence_signals_v85"] = rows\n            e["player_intelligence_v85_captured_at"] = now.isoformat()\n            captured += 1\n        out.append(e)\n    return out, captured, settled\n\n\ndef _brier(y, p):\n    return None if not y else sum((float(pi) - float(yi)) ** 2 for yi, pi in zip(y, p)) / len(y)\n\n\ndef _logloss(y, p):\n    if not y:\n        return None\n    s = 0.0\n    for yi, pi in zip(y, p):\n        pi = _clamp(pi, 1e-6, 1 - 1e-6)\n        s += -(yi * math.log(pi) + (1 - yi) * math.log(1 - pi))\n    return s / len(y)\n\n\ndef _summary(rows: list[tuple[int, float]]) -> dict:\n    if not rows:\n        return {"n": 0, "selected_n": 0, "accuracy": None, "brier": None, "log_loss": None}\n    y, p = [r[0] for r in rows], [r[1] for r in rows]\n    selected = [r for r in rows if r[1] >= SELECT_THRESHOLD]\n    return {\n        "n": len(rows),\n        "selected_n": len(selected),\n        "accuracy": round(100 * sum(r[0] for r in selected) / len(selected), 1) if selected else None,\n        "brier": round(_brier(y, p), 5),\n        "log_loss": round(_logloss(y, p), 5),\n    }\n\n\ndef _series(rows: list[dict], key: str) -> list[dict]:\n    vals = []\n    for r in sorted(rows, key=lambda x: x.get("scheduled_time") or ""):\n        p = _prob(r.get(key))\n        if p is None or p < SELECT_THRESHOLD:\n            continue\n        vals.append(1 if r.get("result") == "hit" else 0)\n    out = []\n    for i in range(4, len(vals)):\n        w = vals[max(0, i - 7): i + 1]\n        out.append({"n": i + 1, "accuracy": round(100 * sum(w) / len(w), 1)})\n    return out[-24:]\n\n\ndef _telemetry(history: list[dict]) -> dict:\n    rows = []\n    pairs = defaultdict(list)\n    surfaces = defaultdict(lambda: defaultdict(list))\n    for e in history or []:\n        for s in e.get("player_intelligence_signals_v85") or []:\n            if s.get("result") not in ("hit", "miss"):\n                continue\n            y = 1 if s.get("result") == "hit" else 0\n            row = {\n                **s,\n                "scheduled_time": e.get("scheduled_time"),\n                "surface": _surface(e.get("surface")),\n                "result": s.get("result"),\n            }\n            rows.append(row)\n            for name, field in (("player", "player_probability"), ("ensemble", "ensemble_base"), ("ensemble_player_shadow", "shadow_score")):\n                p = _prob(s.get(field))\n                if p is not None:\n                    pairs[name].append((y, p))\n                    surfaces[row["surface"]][name].append((y, p))\n            if s.get("generator_shadow_selected"):\n                p = _prob(s.get("shadow_score"))\n                if p is not None:\n                    pairs["generator_player_shadow"].append((y, p))\n    models = {k: _summary(v) for k, v in pairs.items()}\n    for name, field in (("player", "player_probability"), ("ensemble", "ensemble_base"), ("ensemble_player_shadow", "shadow_score")):\n        models.setdefault(name, _summary([]))\n        models[name]["series"] = _series(rows, field)\n    by_surface = {surf: {k: _summary(v) for k, v in groups.items()} for surf, groups in surfaces.items()}\n    return {\n        "version": VERSION,\n        "mode": "SHADOW",\n        "settled_rows": len(rows),\n        "models": models,\n        "by_surface": by_surface,\n        "production_influence": False,\n        "generator_assist": "bounded_ui_composer_support",\n        "note": "Player Intelligence używa wyłącznie danych dostępnych przed meczem i istniejącego cache; nie wykonuje własnych requestów API.",\n    }\n\n\ndef post(now=None) -> dict:\n    now = now or datetime.now(timezone.utc)\n    results = _read(RESULTS_PATH, [])\n    history = _read(HISTORY_PATH, [])\n    meta = _read(META_PATH, {})\n    telemetry = _read(TELEMETRY_PATH, {})\n    if not isinstance(results, list): results = []\n    if not isinstance(history, list): history = []\n    results = _decorate_post(results)\n    history, captured, settled = _capture_and_settle(history, results, now)\n    pi_tel = _telemetry(history)\n    if not isinstance(telemetry, dict): telemetry = {}\n    telemetry["player_intelligence_v85"] = pi_tel\n    if not isinstance(meta, dict): meta = {}\n    meta.update({\n        "player_intelligence_v85_version": VERSION,\n        "player_intelligence_v85_mode": "SHADOW",\n        "player_intelligence_v85_captured": captured,\n        "player_intelligence_v85_settled_this_run": settled,\n        "player_intelligence_v85_settled_total": pi_tel.get("settled_rows", 0),\n        "player_intelligence_v85_api_calls": 0,\n        "player_intelligence_v85_updated_at": now.isoformat(),\n    })\n    _write(RESULTS_PATH, results)\n    _write(HISTORY_PATH, history)\n    _write(TELEMETRY_PATH, telemetry)\n    _write(META_PATH, meta)\n    return {"status": "ok", "captured": captured, "settled": settled, "telemetry_rows": pi_tel.get("settled_rows", 0)}\n\n\ndef main():\n    import argparse\n    ap = argparse.ArgumentParser()\n    ap.add_argument("mode", choices=("pre", "post"), nargs="?", default="pre")\n    args = ap.parse_args()\n    result = pre() if args.mode == "pre" else post()\n    print(json.dumps(result, ensure_ascii=False, indent=2))\n\n\nif __name__ == "__main__":\n    main()\n',
    'frontend/player-intelligence-v85.js': '/* Tenis AI v8.5 — Player Intelligence UI\n   Cache-first backend data only. No extra fetch, no MutationObserver, no interval.\n*/\n(() => {\n  \'use strict\';\n  const VERSION=\'v8.5\';\n  const esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\n  const num=x=>Number.isFinite(Number(x))?Number(x):null;\n  const norm=s=>String(s??\'\').normalize(\'NFKD\').replace(/[\\u0300-\\u036f]/g,\'\').toLowerCase().replace(/[^a-z0-9]+/g,\' \').trim();\n  const signed=x=>num(x)==null?\'—\':`${Number(x)>0?\'+\':\'\'}${Number(x).toFixed(1)}`;\n  const pct=x=>num(x)==null?\'—\':`${Number(x).toFixed(1).replace(\'.0\',\'\')}%`;\n  const qualityClass=q=>String(q||\'N/D\').toLowerCase().replace(\'/\',\'-\');\n  const rows=()=>{try{return typeof all!==\'undefined\'&&Array.isArray(all)?all:[]}catch{return []}};\n  const mkey=m=>String(m?.id??m?.match_id??[m?.p1,m?.p2,m?.scheduled_time].join(\'|\'));\n\n  function signalKey(s){return String(s?.key||s?.signal_key||`${s?.market||\'\'}|${s?.pick||\'\'}`)}\n  function supportFor(m,s){\n    const by=m?.autolearn_v84?.by_key||{};\n    const row=by[signalKey(s)]||{};\n    const pi=row?.player_intelligence_v85||null;\n    return pi&&num(pi.probability)!=null?pi:null;\n  }\n  function matchForNames(text){\n    const t=norm(text);\n    return rows().find(m=>t.includes(norm(m?.p1))&&t.includes(norm(m?.p2)))||null;\n  }\n  function metric(profile,key,w=\'10\'){\n    const x=profile?.windows?.[String(w)]?.metrics?.[key]||{};\n    const v=num(x.adjusted);return v==null?null:(v<=1?v*100:v);\n  }\n  function index(profile,key){return num(profile?.indexes?.[key])}\n  function sample(profile,w){return Number(profile?.windows?.[String(w)]?.sample_matches||0)}\n\n  function compact(m){\n    const pi=m?.player_intelligence_v85||{},mu=pi.matchup||{};\n    if(!pi.version)return \'\';\n    const q=mu.quality||\'N/D\',edge=num(mu.edge_p1);\n    const lead=edge==null?\'profil N/D\':Math.abs(edge)<2?\'matchup równy\':`${edge>0?esc(m.p1):esc(m.p2)} ${signed(Math.abs(edge))}`;\n    return `<div class="pi85-compact q-${qualityClass(q)}"><span>🧬 Player Intelligence</span><b>${lead}</b><em>${esc(q)}</em></div>`;\n  }\n\n  function profileCol(name,p){\n    const ix=p?.indexes||{};\n    return `<article class="pi85-player"><header><b>${esc(name)}</b><em>${esc(p?.quality||\'N/D\')}</em></header>\n      <div class="pi85-kpis">\n        <span><small>Serwis</small><b>${index(p,\'serve\')==null?\'—\':Math.round(index(p,\'serve\'))}</b></span>\n        <span><small>Return</small><b>${index(p,\'return\')==null?\'—\':Math.round(index(p,\'return\'))}</b></span>\n        <span><small>Forma</small><b>${index(p,\'form\')==null?\'—\':Math.round(index(p,\'form\'))}</b></span>\n        <span><small>Mental</small><b>${index(p,\'mental\')==null?\'—\':Math.round(index(p,\'mental\'))}</b></span>\n      </div>\n      <div class="pi85-window-row"><span>L5 <b>${sample(p,5)}</b></span><span>L10 <b>${sample(p,10)}</b></span><span>L20 <b>${sample(p,20)}</b></span></div>\n      <small class="pi85-sub">Hold ${pct(metric(p,\'hold_rate\'))} · Return ${pct(metric(p,\'return_points_won\'))} · 1S ${pct(metric(p,\'first_set_won\'))}</small>\n      <small class="pi85-sub">BO5 obserw. ${Number(p?.windows?.[\'20\']?.bo5_observed||0)} · S4 ${pct((p?.windows?.[\'20\']?.set4_win||{}).adjusted<=1?(p?.windows?.[\'20\']?.set4_win||{}).adjusted*100:(p?.windows?.[\'20\']?.set4_win||{}).adjusted)} · S5 ${pct((p?.windows?.[\'20\']?.set5_win||{}).adjusted<=1?(p?.windows?.[\'20\']?.set5_win||{}).adjusted*100:(p?.windows?.[\'20\']?.set5_win||{}).adjusted)}</small>\n    </article>`;\n  }\n\n  function details(m){\n    const pi=m?.player_intelligence_v85||{},pr=pi.profiles||{},mu=pi.matchup||{};\n    if(!pi.version)return \'\';\n    const reasons=(mu.reasons||[]).map(r=>`<span>${esc(r.factor)}: ${Number(r.edge_p1)>0?esc(m.p1):esc(m.p2)} ${Math.abs(Number(r.edge_p1||0)).toFixed(1)}</span>`).join(\'\');\n    return `<section class="pi85-match-block">\n      <header class="pi85-head"><div><b>🧬 Player Intelligence v8.5</b><small>${esc(String(pi.surface||m.surface||\'\').toUpperCase())} · L5/L10/L20 · dane przedmeczowe</small></div><em>SHADOW</em></header>\n      <div class="pi85-matchup"><span>Jakość profilu <b>${esc(mu.quality||\'N/D\')}</b></span><span>Matchup P1 <b>${signed(mu.edge_p1)}</b></span><span>Format <b>${mu.best_of?`BO${mu.best_of}`:\'N/D\'}</b></span></div>\n      <div class="pi85-players">${profileCol(m.p1,pr.p1)}${profileCol(m.p2,pr.p2)}</div>\n      ${reasons?`<div class="pi85-reasons">${reasons}</div>`:\'\'}\n      <p class="pi85-note">Profile są liczone wyłącznie z tej samej nawierzchni. Zakres główny 12 miesięcy; do 24 miesięcy tylko fallback przy małej próbce. Player nie wykonuje własnych requestów API.</p>\n    </section>`;\n  }\n\n  function decorateMatches(){\n    document.querySelectorAll(\'.match-card\').forEach(card=>{\n      if(card.dataset.pi85===\'1\')return;\n      const m=matchForNames(card.querySelector(\'.match-players\')?.textContent||\'\');if(!m)return;\n      const c=compact(m),d=details(m);if(!c&&!d)return;\n      const main=card.querySelector(\'.match-main\');if(c&&main)main.insertAdjacentHTML(\'beforeend\',c);\n      const detail=card.querySelector(\'.match-detail\');if(d&&detail)detail.insertAdjacentHTML(\'afterbegin\',d);\n      card.dataset.pi85=\'1\';\n    });\n  }\n\n  function profileForName(name){\n    const m=rows().find(x=>norm(x?.p1)===norm(name)||norm(x?.p2)===norm(name));\n    if(!m)return null;\n    const side=norm(m.p1)===norm(name)?\'p1\':\'p2\';\n    return {match:m,side,profile:m?.player_intelligence_v85?.profiles?.[side]||null};\n  }\n  function injectPlayerPanel(name){\n    const host=document.querySelector(\'#player-analytics-v76\');if(!host||host.querySelector(\'.pi85-profile-addon\'))return;\n    const x=profileForName(name);if(!x?.profile)return;\n    const p=x.profile;\n    const html=`<details class="pa76-details pi85-profile-addon"><summary>🧬 Player Intelligence v8.5 · profil skorygowany <i>⌄</i></summary>\n      <div class="pi85-profile-grid">\n        <span><small>Jakość</small><b>${esc(p.quality||\'N/D\')}</b></span>\n        <span><small>Serwis adj.</small><b>${index(p,\'serve\')==null?\'—\':Math.round(index(p,\'serve\'))}</b></span>\n        <span><small>Return adj.</small><b>${index(p,\'return\')==null?\'—\':Math.round(index(p,\'return\'))}</b></span>\n        <span><small>Forma adj.</small><b>${index(p,\'form\')==null?\'—\':Math.round(index(p,\'form\'))}</b></span>\n        <span><small>L5/L10/L20</small><b>${sample(p,5)}/${sample(p,10)}/${sample(p,20)}</b></span>\n        <span><small>Fallback 24m</small><b>${p.fallback_used?\'TAK\':\'NIE\'}</b></span>\n      </div>\n      <p class="pi85-note">Adjusted = świeżość + jakość rywali + shrinkage do średniej nawierzchni. Nie jest to prawdopodobieństwo wygranej.</p>\n    </details>`;\n    host.querySelector(\'#pa76-content\')?.insertAdjacentHTML(\'beforeend\',html);\n  }\n\n  function spark(series,cls){\n    const vals=(Array.isArray(series)?series:[]).map(x=>num(x?.accuracy)).filter(x=>x!=null);\n    if(vals.length<2)return \'<div class="pi85-spark-empty">wykres po kolejnych rozliczeniach</div>\';\n    const W=260,H=60,P=5,lo=Math.max(0,Math.min(...vals)-5),hi=Math.min(100,Math.max(...vals)+5),den=Math.max(8,hi-lo);\n    const pts=vals.map((v,i)=>`${(P+i*(W-2*P)/Math.max(1,vals.length-1)).toFixed(1)},${(H-P-(v-lo)/den*(H-2*P)).toFixed(1)}`).join(\' \');\n    return `<svg class="pi85-spark ${cls}" viewBox="0 0 ${W} ${H}"><polyline points="${pts}"/></svg>`;\n  }\n  function telCard(label,x,icon){\n    return `<article class="pi85-tel-card"><header><span>${icon}</span><b>${esc(label)}</b></header>${spark(x?.series,label.toLowerCase().replace(/\\W+/g,\'-\'))}\n      <div><span><small>Accuracy ≥65</small><b>${pct(x?.accuracy)}</b></span><span><small>Brier</small><b>${num(x?.brier)==null?\'—\':Number(x.brier).toFixed(3)}</b></span><span><small>n</small><b>${Number(x?.selected_n||0)}</b></span></div></article>`;\n  }\n  async function injectStats(){\n    const app=document.querySelector(\'#app\');if(!app||document.querySelector(\'#pi85-stats\'))return;\n    const api=window.TENIS_AI_AUTOLEARN_V84;if(!api?.loadTelemetry)return;\n    const tel=await api.loadTelemetry();const pi=tel?.player_intelligence_v85;if(!pi||document.querySelector(\'#pi85-stats\'))return;\n    const m=pi.models||{};\n    const html=`<section id="pi85-stats" class="pi85-stats"><header class="pi85-head"><div><b>🧬 Player Intelligence v8.5</b><small>Player vs Ensemble vs Ensemble+Player</small></div><em>SHADOW</em></header>\n      <div class="pi85-tel-grid">${telCard(\'Player\',m.player,\'🧬\')}${telCard(\'Ensemble\',m.ensemble,\'🔗\')}${telCard(\'Ensemble + Player\',m.ensemble_player_shadow,\'⚡\')}</div>\n      <div class="pi85-surface-stats">${Object.entries(pi.by_surface||{}).map(([s,v])=>`<span><b>${esc(s.toUpperCase())}</b> ${pct(v?.ensemble_player_shadow?.accuracy)} · n=${Number(v?.ensemble_player_shadow?.selected_n||0)}</span>`).join(\'\')}</div>\n      <p class="pi85-note">Monitoring, nie autopilot: Player nie zmienia wag produkcyjnych. Generator może dostać wyłącznie mały, ograniczony bonus/karę jakościową.</p></section>`;\n    app.insertAdjacentHTML(\'afterbegin\',html);\n  }\n\n  function wrapRenderers(){\n    try{\n      if(typeof renderMatches===\'function\'&&!renderMatches.__pi85){const base=renderMatches;renderMatches=function(){const v=base.apply(this,arguments);decorateMatches();return v};renderMatches.__pi85=true}\n      if(typeof renderStats===\'function\'&&!renderStats.__pi85){const base=renderStats;renderStats=function(){const v=base.apply(this,arguments);injectStats();return v};renderStats.__pi85=true}\n    }catch{}\n    const pa=window.TENIS_AI_PLAYER_ANALYTICS_V801;\n    if(pa?.mount&&!pa.mount.__pi85){const base=pa.mount;const f=function(name){const v=base.apply(this,arguments);injectPlayerPanel(name);return v};f.__pi85=true;pa.mount=f}\n  }\n\n  wrapRenderers();\n  if(document.querySelector(\'.match-card\'))decorateMatches();\n  if(document.querySelector(\'#app\')&&document.querySelector(\'.stats-hero\'))injectStats();\n  window.TENIS_AI_PLAYER_V85=Object.freeze({version:VERSION,supportFor,decorateMatches,injectStats});\n})();\n',
    'frontend/player-intelligence-v85.css': '/* Tenis AI v8.5 Player Intelligence */\n.pi85-compact{display:flex;gap:.45rem;align-items:center;flex-wrap:wrap;margin-top:.45rem;padding:.38rem .55rem;border:1px solid rgba(78,221,255,.20);border-radius:10px;background:rgba(5,25,38,.72);font-size:.76rem}.pi85-compact span{color:#6be4ff}.pi85-compact b{color:#eefaff}.pi85-compact em{margin-left:auto;font-style:normal;font-size:.68rem;padding:.16rem .38rem;border-radius:999px;background:rgba(157,255,74,.10);color:#b7ff61}.pi85-compact.q-n-d em,.pi85-compact.q-low em{color:#ffb28f;background:rgba(255,122,87,.10)}\n.pi85-match-block,.pi85-stats{margin:0 0 1rem;padding:.9rem;border:1px solid rgba(50,213,255,.23);border-radius:16px;background:linear-gradient(180deg,rgba(4,24,36,.94),rgba(2,14,24,.96));box-shadow:inset 0 0 30px rgba(0,195,255,.03)}.pi85-head{display:flex;align-items:center;justify-content:space-between;gap:.8rem;margin-bottom:.7rem}.pi85-head b{color:#eafaff}.pi85-head small{display:block;color:#7d9aab;margin-top:.16rem}.pi85-head em{font-style:normal;color:#b6ff5c;border:1px solid rgba(163,255,72,.25);border-radius:999px;padding:.2rem .5rem;font-size:.68rem}\n.pi85-matchup{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem;margin-bottom:.65rem}.pi85-matchup span,.pi85-profile-grid span{display:flex;flex-direction:column;gap:.1rem;padding:.5rem;border:1px solid rgba(77,190,220,.14);border-radius:10px;background:rgba(4,20,30,.72);font-size:.72rem;color:#7f9aa8}.pi85-matchup b,.pi85-profile-grid b{font-size:.9rem;color:#eafaff}.pi85-players{display:grid;grid-template-columns:1fr 1fr;gap:.55rem}.pi85-player{padding:.6rem;border:1px solid rgba(62,203,238,.14);border-radius:12px;background:rgba(3,18,27,.78)}.pi85-player header{display:flex;justify-content:space-between;gap:.5rem}.pi85-player header b{color:#f0fbff}.pi85-player header em{font-style:normal;color:#b6ff5c;font-size:.67rem}.pi85-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:.35rem;margin:.55rem 0}.pi85-kpis span{text-align:center}.pi85-kpis small{display:block;color:#7793a3;font-size:.62rem}.pi85-kpis b{font-size:1.02rem;color:#dff9ff}.pi85-window-row{display:flex;gap:.35rem}.pi85-window-row span{flex:1;text-align:center;padding:.28rem;border-radius:8px;background:rgba(35,132,157,.10);font-size:.68rem;color:#8da6b4}.pi85-sub{display:block;margin-top:.5rem;color:#8ea6b2}.pi85-reasons{display:flex;gap:.35rem;flex-wrap:wrap;margin-top:.6rem}.pi85-reasons span{padding:.25rem .45rem;border-radius:999px;background:rgba(54,183,216,.09);color:#a9dceb;font-size:.68rem}.pi85-note{margin:.65rem 0 0;color:#78909d;font-size:.7rem;line-height:1.45}\n.pi85-profile-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.45rem;padding:.25rem 0}.pi85-profile-addon{border-top:1px solid rgba(48,200,236,.15)}\n.pi85-tel-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem}.pi85-tel-card{padding:.65rem;border:1px solid rgba(52,197,229,.16);border-radius:12px;background:rgba(2,18,27,.78)}.pi85-tel-card header{display:flex;gap:.4rem;align-items:center}.pi85-tel-card header b{color:#e9faff}.pi85-tel-card>div{display:grid;grid-template-columns:repeat(3,1fr);gap:.3rem}.pi85-tel-card>div span{text-align:center}.pi85-tel-card small{display:block;color:#76909e;font-size:.6rem}.pi85-tel-card b{color:#e6fbff}.pi85-spark{width:100%;height:62px;margin:.4rem 0;overflow:visible}.pi85-spark polyline{fill:none;stroke:currentColor;stroke-width:2.3;vector-effect:non-scaling-stroke}.pi85-spark.player{color:#7ce9ff}.pi85-spark.ensemble{color:#b5c7d2}.pi85-spark.ensemble-player{color:#b9ff5e}.pi85-spark-empty{height:62px;display:grid;place-items:center;color:#667f8c;font-size:.68rem}.pi85-surface-stats{display:flex;gap:.4rem;flex-wrap:wrap;margin-top:.65rem}.pi85-surface-stats span{padding:.3rem .5rem;border-radius:999px;background:rgba(50,189,221,.08);font-size:.68rem;color:#a8c6d4}\n@media(max-width:720px){.pi85-matchup,.pi85-profile-grid{grid-template-columns:1fr 1fr}.pi85-players,.pi85-tel-grid{grid-template-columns:1fr}.pi85-kpis{grid-template-columns:repeat(4,1fr)}.pi85-match-block,.pi85-stats{padding:.72rem}.pi85-head{align-items:flex-start}.pi85-compact em{margin-left:0}}\n',
    'scripts/verify_v85.py': 'from pathlib import Path\n\nROOT=Path(__file__).resolve().parents[1]\nchecks=[]\n\ndef ok(name, cond, detail=\'\'):\n    checks.append((name,bool(cond),detail))\n\nbackend=(ROOT/\'backend/player_intelligence_v85.py\').read_text(encoding=\'utf-8\')\nfront=(ROOT/\'frontend/player-intelligence-v85.js\').read_text(encoding=\'utf-8\')\nindex=(ROOT/\'frontend/index.html\').read_text(encoding=\'utf-8\')\nworkflow=(ROOT/\'.github/workflows/update-and-pages.yml\').read_text(encoding=\'utf-8\')\nscenario=(ROOT/\'frontend/scenario-studio-v82a.js\').read_text(encoding=\'utf-8\')\n\nok(\'backend version\', \'VERSION = "v8.5"\' in backend)\nok(\'cache-first zero API\', \'"api_calls": 0\' in backend and \'requests.\' not in backend)\nok(\'same-surface policy\', \'same_surface_only\' in backend)\nok(\'L5/L10/L20\', \'WINDOWS = (5, 10, 20)\' in backend)\nok(\'12m + 24m fallback\', \'PRIMARY_DAYS = 365\' in backend and \'FALLBACK_DAYS = 730\' in backend)\nok(\'set 4/5 support\', \'set4_won\' in backend and \'set5_won\' in backend)\nok(\'shadow bounded\', \'"HIGH": (.25, .04)\' in backend and \'production_influence\' in backend)\nok(\'frontend no fetch\', \'fetch(\' not in front)\nok(\'frontend no observer\', \'new MutationObserver(\' not in front)\nok(\'frontend no interval\', \'setInterval\' not in front)\nok(\'index css once\', index.count(\'player-intelligence-v85.css?v=85a1\')==1)\nok(\'index js once\', index.count(\'player-intelligence-v85.js?v=85a1\')==1)\nok(\'workflow pre\', \'Player Intelligence v8.5 PRE\' in workflow)\nok(\'workflow post\', \'Player Intelligence v8.5 POST\' in workflow)\nok(\'workflow guard\', \'Player Intelligence Guard v8.5\' in workflow)\nok(\'generator assist marker\', \'PLAYER_INTELLIGENCE_V85_ASSIST\' in scenario)\nok(\'protected app pin\', \'app.js?v=84b1\' in index)\nok(\'protected autolearn pin\', \'autolearn-v84.js?v=84a1&hf=84b1\' in index)\nok(\'protected scenario pin\', \'scenario-studio-v82a.js?v=82a6&hf=84a1\' in index)\n\nfailed=[x for x in checks if not x[1]]\nfor name,status,detail in checks:\n    print((\'PASS\' if status else \'FAIL\')+\': \'+name+(f\' — {detail}\' if detail else \'\'))\nif failed:\n    raise SystemExit(f\'v8.5 guard failed: {len(failed)}\')\nprint(f\'v8.5 guard PASS: {len(checks)} checks\')\n',
    'tests/test_v85_player_intelligence.py': 'from __future__ import annotations\n\nfrom datetime import datetime, timezone\nimport importlib.util\nfrom pathlib import Path\n\nimport pandas as pd\n\nMODULE = Path(__file__).resolve().parents[1] / "backend" / "player_intelligence_v85.py"\nspec = importlib.util.spec_from_file_location("player_intelligence_v85", MODULE)\npi = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(pi)\n\n\ndef _df():\n    rows=[]\n    base=pd.Timestamp("2026-08-20")\n    for i in range(12):\n        rows.append({\n            "date": base-pd.Timedelta(days=i*10), "surface":"hard", "player":"A", "player_key":"a",\n            "opponent":"X", "opponent_rank":50+i*10, "rank":20, "won":1.0 if i<8 else 0.0,\n            "hold_rate":.82, "break_rate":.31, "serve_points_won":.64, "return_points_won":.41,\n            "first_serve_won":.72, "second_serve_won":.53, "first_set_won":.7, "second_set_won":.65,\n            "second_after_first_win":.7, "second_after_first_loss":.55, "third_set_won":.6,\n            "first_set_over85":.8, "first_set_over95":.55, "first_set_over105":.3, "sets_played":3,\n        })\n    for i in range(20):\n        rows.append({\n            "date": base-pd.Timedelta(days=i*8), "surface":"clay", "player":"A", "player_key":"a",\n            "opponent":"Y", "opponent_rank":200, "rank":20, "won":0.0,\n            "hold_rate":.60, "break_rate":.20, "serve_points_won":.55, "return_points_won":.34,\n            "first_serve_won":.62, "second_serve_won":.42, "first_set_won":.2, "second_set_won":.2,\n            "second_after_first_win":.2, "second_after_first_loss":.2, "third_set_won":.2,\n            "first_set_over85":.4, "first_set_over95":.25, "first_set_over105":.1, "sets_played":2,\n        })\n    for i in range(12):\n        rows.append({\n            "date": base-pd.Timedelta(days=i*10), "surface":"hard", "player":"B", "player_key":"b",\n            "opponent":"Z", "opponent_rank":300+i*5, "rank":90, "won":1.0 if i<5 else 0.0,\n            "hold_rate":.72, "break_rate":.24, "serve_points_won":.58, "return_points_won":.37,\n            "first_serve_won":.66, "second_serve_won":.45, "first_set_won":.45, "second_set_won":.45,\n            "second_after_first_win":.5, "second_after_first_loss":.4, "third_set_won":.45,\n            "first_set_over85":.72, "first_set_over95":.48, "first_set_over105":.25, "sets_played":2,\n        })\n    return pd.DataFrame(rows)\n\n\ndef test_profile_uses_same_surface_only():\n    p=pi.build_profile(_df(),"A","hard","2026-08-24T12:00:00Z",80)\n    assert p["surface"]=="hard"\n    assert p["sample_matches"]==12\n    hold=p["windows"]["10"]["metrics"]["hold_rate"]["raw"]\n    assert hold > .80\n\n\ndef test_windows_are_5_10_20_and_quality():\n    p=pi.build_profile(_df(),"A","hard","2026-08-24T12:00:00Z",80)\n    assert set(p["windows"])=={"5","10","20"}\n    assert p["windows"]["5"]["sample_matches"]==5\n    assert p["windows"]["10"]["sample_matches"]==10\n    assert p["quality"] in {"HIGH","MEDIUM"}\n\n\ndef test_shadow_is_bounded():\n    s,shift=pi._shadow(.70,.95,"HIGH")\n    assert round(shift,6) <= .04\n    assert s <= .74\n    s2,shift2=pi._shadow(.70,.20,"MEDIUM")\n    assert shift2 >= -.02\n    assert s2 >= .6799\n\n\ndef test_winner_probability_favors_stronger_profile():\n    df=_df()\n    a=pi.build_profile(df,"A","hard","2026-08-24T12:00:00Z",80)\n    b=pi.build_profile(df,"B","hard","2026-08-24T12:00:00Z",55)\n    p=pi._winner_probability(a,b,1)\n    assert p is not None and p > .5\n\n\ndef test_over_probability_available_for_first_set_lines():\n    df=_df()\n    a=pi.build_profile(df,"A","hard","2026-08-24T12:00:00Z",80)\n    b=pi.build_profile(df,"B","hard","2026-08-24T12:00:00Z",55)\n    p=pi._over_probability(a,b,8.5)\n    assert p is not None and .2 <= p <= .9\n\n\ndef test_no_cross_surface_fallback():\n    df=_df()\n    p=pi.build_profile(df,"A","grass","2026-08-24T12:00:00Z",None)\n    assert p["sample_matches"]==0\n    assert p["quality"]=="N/D"\n\ndef test_parse_up_to_five_sets():\n    assert pi._set_pairs(\'6-4 3-6 7-6 2-6 6-3\') == [(6,4),(3,6),(7,6),(2,6),(6,3)]\n',
}

def write(path, content):
    p=ROOT/path
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(content,encoding='utf-8')


def patch_once(path, old, new, marker):
    p=ROOT/path
    text=p.read_text(encoding='utf-8')
    if marker in text:
        return False
    if old not in text:
        raise RuntimeError(f'Nie znaleziono punktu patchowania {path}: {marker}')
    p.write_text(text.replace(old,new,1),encoding='utf-8')
    return True


def main():
    for path,content in FILES.items():
        write(path,content)

    patch_once(
        'frontend/index.html',
        '  <link rel="stylesheet" href="model-trends-v84e2.css?v=84e2">',
        '  <link rel="stylesheet" href="model-trends-v84e2.css?v=84e2">\n  <link rel="stylesheet" href="player-intelligence-v85.css?v=85a1">',
        'player-intelligence-v85.css?v=85a1'
    )
    patch_once(
        'frontend/index.html',
        '  <script src="model-trends-v84e2.js?v=84e2"></script>',
        '  <script src="model-trends-v84e2.js?v=84e2"></script>\n  <script src="player-intelligence-v85.js?v=85a1"></script>',
        'player-intelligence-v85.js?v=85a1'
    )

    patch_once(
        '.github/workflows/update-and-pages.yml',
        '      - name: Prediction integrity gate v7.8A\n        run: python backend/prediction_integrity_v78a.py',
        '      - name: Player Intelligence v8.5 PRE\n        run: python backend/player_intelligence_v85.py pre\n      - name: Prediction integrity gate v7.8A\n        run: python backend/prediction_integrity_v78a.py',
        'Player Intelligence v8.5 PRE'
    )
    patch_once(
        '.github/workflows/update-and-pages.yml',
        '      - name: AutoLearn Integration Guard v8.4A\n        run: python scripts/verify_v84a.py',
        '      - name: Player Intelligence v8.5 POST\n        run: python backend/player_intelligence_v85.py post\n      - name: Player Intelligence Guard v8.5\n        run: python scripts/verify_v85.py\n      - name: AutoLearn Integration Guard v8.4A\n        run: python scripts/verify_v84a.py',
        'Player Intelligence v8.5 POST'
    )

    scenario=ROOT/'frontend/scenario-studio-v82a.js'
    s=scenario.read_text(encoding='utf-8')
    if 'PLAYER_INTELLIGENCE_V85_ASSIST' not in s:
        helper='''
  // PLAYER_INTELLIGENCE_V85_ASSIST — bounded support only; production Ensemble weights stay untouched.
  function playerAssist(m,s){
    try{return window.TENIS_AI_PLAYER_V85?.supportFor?.(m,s)||null}catch{return null}
  }
  function playerBadge(m,s){
    const p=playerAssist(m,s),v=num(p?.support_score);
    return v==null?'':` · 🧬 ${v>=0?'+':''}${Math.round(v)}`;
  }
'''
        needle="  function composerSignalScore(m,s,profile='balanced'){"
        if needle not in s: raise RuntimeError('scenario helper anchor missing')
        s=s.replace(needle,helper+'\n'+needle,1)
        old='    if(ensemble<p.mlFloor&&legacy<p.legacyRescue)score=Math.min(score,p.floor-.5);\n    return clamp(score);'
        new='''    if(ensemble<p.mlFloor&&legacy<p.legacyRescue)score=Math.min(score,p.floor-.5);
    // v8.5: small bounded Generator assist. This does NOT alter Ensemble model weights.
    const pi=playerAssist(m,s);
    const ps=num(pi?.support_score),pq=String(pi?.quality||'N/D').toUpperCase();
    if(ps!=null&&pq!=='N/D'){
      const cap=pq==='HIGH'?2:pq==='MEDIUM'?1:.5;
      score+=Math.max(-cap,Math.min(cap,ps*.20));
    }
    return clamp(score);'''
        if old not in s: raise RuntimeError('scenario composer anchor missing')
        s=s.replace(old,new,1)
        old2='const mk=matchKey(m);const ml=autoLearnSnapshot(m,s);const finalScore=composerSignalScore(m,s,profile);'
        new2='const mk=matchKey(m);const ml=autoLearnSnapshot(m,s);const pi=playerAssist(m,s);const finalScore=composerSignalScore(m,s,profile);'
        if old2 not in s: raise RuntimeError('scenario addSignal anchor missing')
        s=s.replace(old2,new2,1)
        old3='      autolearn_v84:ml?{current:ml.current??null,catboost:ml.catboost??null,tabpfn:ml.tabpfn??null,ensemble:ml.ensemble??null,weights:ml.weights||null}:null,\n      source,quality:'
        new3='''      autolearn_v84:ml?{current:ml.current??null,catboost:ml.catboost??null,tabpfn:ml.tabpfn??null,ensemble:ml.ensemble??null,weights:ml.weights||null}:null,
      player_intelligence_v85:pi?{probability:pi.probability??null,shadow_score:pi.shadow_score??null,support_score:pi.support_score??null,quality:pi.quality??null}:null,
      source,quality:'''
        if old3 not in s: raise RuntimeError('scenario snapshot anchor missing')
        s=s.replace(old3,new3,1)
        old4='<small>${esc(activeModelName())} · ${esc(categoryOf(s))}</small>'
        new4='<small>${esc(activeModelName())} · ${esc(categoryOf(s))}${playerBadge(m,s)}</small>'
        if old4 not in s: raise RuntimeError('scenario manual badge anchor missing')
        s=s.replace(old4,new4,1)
        scenario.write_text(s,encoding='utf-8')

    for rel in ('v85_install.py',):
        p=ROOT/rel
        if p.exists():
            p.unlink()

    print('v8.5 Player Intelligence files generated and repo patched successfully.')


if __name__=='__main__':
    main()
